query:
SELECT id, company_name, industry, status FROM projects WHERE company_name = '海豚知道';
SELECT COUNT(*) AS question_count, SUM(CASE WHEN source IN ('manual','csv') OR question_type='指定问题' THEN 1 ELSE 0 END) AS specified_question_count FROM questions WHERE project_id = (SELECT id FROM projects WHERE company_name='海豚知道' LIMIT 1);
SELECT COUNT(*) AS analysis_count, SUM(CASE WHEN manually_reviewed=1 THEN 1 ELSE 0 END) AS reviewed_count FROM analysis_results WHERE project_id = (SELECT id FROM projects WHERE company_name='海豚知道' LIMIT 1);
SELECT id, task_name, task_type, priority, status, need_retest, published_url FROM optimization_tasks WHERE project_id = (SELECT id FROM projects WHERE company_name='海豚知道' LIMIT 1) ORDER BY FIELD(priority,'P0','P1','P2'), id LIMIT 10;
SELECT COUNT(*) AS article_count FROM geo_articles WHERE project_id = (SELECT id FROM projects WHERE company_name='海豚知道' LIMIT 1);
SELECT COUNT(*) AS publication_count FROM geo_publications WHERE project_id = (SELECT id FROM projects WHERE company_name='海豚知道' LIMIT 1);

